:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #f5c542;
  --border-width: 4px;
  --shadow-offset: 6px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(-45deg, var(--secondary) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--secondary) 75%),
    linear-gradient(-45deg, transparent 75%, var(--secondary) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.card {
  background-color: var(--card-bg);
  border: var(--border-width) solid var(--primary);
  box-shadow: var(--shadow-offset) var(--shadow-offset) 0 var(--secondary);
  padding: 40px 30px;
  text-align: center;
  max-width: 500px;
  width: 100%;
  image-rendering: pixelated;
}

.title {
  font-size: 1.8rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 20px;
  text-shadow: 2px 2px 0 var(--secondary);
}

.mode-indicator {
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--primary);
  margin-bottom: 10px;
}

.timer {
  font-size: 4.5rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 20px 0 30px;
  color: var(--text);
  text-shadow: 3px 3px 0 var(--primary);
  line-height: 1.2;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 15px;
  margin-bottom: 20px;
}

.btn {
  background-color: var(--secondary);
  color: var(--text);
  border: var(--border-width) solid var(--primary);
  padding: 12px 24px;
  font-family: inherit;
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--primary);
  transition: transform 0.1s, box-shadow 0.1s, background-color 0.2s;
  min-width: 100px;
}

.btn:hover {
  background-color: var(--primary);
  color: var(--bg);
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--primary);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--primary);
}

.status {
  font-size: 1rem;
  min-height: 1.5em;
  color: var(--accent);
  margin-top: 10px;
}

@media (max-width: 480px) {
  .timer {
    font-size: 3.5rem;
  }
  .card {
    padding: 30px 20px;
  }
  .btn {
    font-size: 1rem;
    padding: 10px 18px;
    min-width: 80px;
  }
}

@media (max-width: 360px) {
  .timer {
    font-size: 2.8rem;
  }
  .btn {
    font-size: 0.9rem;
    padding: 8px 14px;
    min-width: 70px;
  }
}

const WORK_DURATION = 25 * 60;
const BREAK_DURATION = 5 * 60;

let state = {
  mode: 'work',
  remaining: WORK_DURATION,
  running: false,
  endTime: null,
  intervalId: null
};

const timerDisplay = document.getElementById('timerDisplay');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const switchModeBtn = document.getElementById('switchModeBtn');
const modeIndicator = document.getElementById('modeIndicator');
const statusMessage = document.getElementById('statusMessage');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(state.remaining);
  modeIndicator.textContent = state.mode === 'work' ? 'Work' : 'Break';
  startPauseBtn.textContent = state.running ? 'Pause' : 'Start';
  startPauseBtn.setAttribute('aria-label', state.running ? 'Pause timer' : 'Start timer');
  switchModeBtn.textContent = state.mode === 'work' ? 'Break' : 'Work';
  switchModeBtn.setAttribute('aria-label', state.mode === 'work' ? 'Switch to break mode' : 'Switch to work mode');
}

function tick() {
  if (!state.running) return;
  const now = Date.now();
  const remaining = Math.max(0, Math.round((state.endTime - now) / 1000));
  state.remaining = remaining;
  updateDisplay();
  if (remaining <= 0) {
    stopTimer();
    statusMessage.textContent = state.mode === 'work' ? 'Work session complete! Time for a break.' : 'Break complete! Ready for work.';
    startPauseBtn.disabled = true;
  }
}

function startTimer() {
  if (state.running) return;
  state.running = true;
  state.endTime = Date.now() + state.remaining * 1000;
  state.intervalId = setInterval(tick, 200);
  statusMessage.textContent = '';
  startPauseBtn.disabled = false;
  updateDisplay();
}

function stopTimer() {
  state.running = false;
  clearInterval(state.intervalId);
  state.intervalId = null;
  updateDisplay();
}

function resetTimer() {
  stopTimer();
  state.remaining = state.mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  statusMessage.textContent = '';
  startPauseBtn.disabled = false;
  updateDisplay();
}

function switchMode() {
  stopTimer();
  state.mode = state.mode === 'work' ? 'break' : 'work';
  state.remaining = state.mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  statusMessage.textContent = '';
  startPauseBtn.disabled = false;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (state.running) {
    stopTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);
switchModeBtn.addEventListener('click', switchMode);

updateDisplay();
